+          const data = event.data;
+          if (
+            typeof data === 'string' &&
+            data.startsWith(SOCKET_IO_EVENT_PREFIX)
+          ) {
+            try {
+              const payload = JSON.parse(data.slice(SOCKET_IO_PREFIX_LENGTH));
+              if (payload[0] === eventType) {
+                callback(payload[1]);
+              }
+            } catch (e) {
+              // Ignore parse errors
+            }
+          }
+        });
+
+        return ws;
+      }
+    );
+  });
